      node(id:$id){__typename ...BoardIssue ... on Issue{
        boards:projectItems(first:$boardItems){nodes{project{id number fields(first:$nestedFirst){nodes{
          ... on ProjectV2SingleSelectField{__typename id name options{id name}}
